// Procedural character rendering & animation.
// Each fighter is a skeleton (torso, head, 2-segment arms & legs) posed by
// animation functions, drawn with canvas. Local space: feet at (0,0), +y down,
// facing +x (the caller flips with ctx.scale for left-facing).
//
// Angle convention for limb segments: 0 = straight down, +PI/2 = forward,
// PI = straight up, negative = backward.

(function () {
  const { CHARACTERS } = (typeof SHARED !== 'undefined' ? SHARED : require('./shared.js'));

  const BODIES = {
    blaze: { thick: 8,   torso: 30, upArm: 21, foreArm: 20, thigh: 26, shin: 25, headR: 12, hipBase: 47 },
    titan: { thick: 12,  torso: 34, upArm: 23, foreArm: 21, thigh: 27, shin: 25, headR: 11, hipBase: 48 },
    volt:  { thick: 6.5, torso: 28, upArm: 20, foreArm: 19, thigh: 26, shin: 26, headR: 12, hipBase: 48 },
    shade: { thick: 7.5, torso: 30, upArm: 21, foreArm: 20, thigh: 26, shin: 25, headR: 12, hipBase: 47 }
  };

  function shade(hex, f) {
    const n = parseInt(hex.slice(1), 16);
    let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    r = Math.max(0, Math.min(255, Math.round(r * f)));
    g = Math.max(0, Math.min(255, Math.round(g * f)));
    b = Math.max(0, Math.min(255, Math.round(b * f)));
    return `rgb(${r},${g},${b})`;
  }

  function lerp(a, b, u) { return a + (b - a) * u; }
  function clamp01(u) { return Math.max(0, Math.min(1, u)); }
  // cheap deterministic noise for flame flicker
  function jitter(seed) { const s = Math.sin(seed * 127.1) * 43758.5453; return s - Math.floor(s); }

  // -------------------------------------------------------------------------
  // Poses
  // -------------------------------------------------------------------------
  // Fields: lean (torso, +fwd), crouch (px hip drop), head (tilt),
  //   fU/fF (far arm upper/fore), nU/nF (near arm),
  //   fT/fS (far leg thigh/shin), nT/nS (near leg), bob (px, +down)

  function basePose() {
    return { lean: 0.10, crouch: 0, head: 0, bob: 0,
             fU: 0.45, fF: 1.9, nU: 0.75, nF: 2.35,
             fT: -0.30, fS: -0.55, nT: 0.32, nS: 0.12 };
  }

  function lerpPose(a, b, u) {
    const o = {};
    for (const k in a) o[k] = lerp(a[k], b[k], u);
    return o;
  }

  // keyframes: array of [time01, poseOverride]; returns pose at u
  function kf(frames, u) {
    u = clamp01(u);
    for (let i = 0; i < frames.length - 1; i++) {
      const [t0, p0] = frames[i], [t1, p1] = frames[i + 1];
      if (u >= t0 && u <= t1) {
        const f = t1 > t0 ? (u - t0) / (t1 - t0) : 1;
        return lerpPose(Object.assign(basePose(), p0), Object.assign(basePose(), p1), f);
      }
    }
    return Object.assign(basePose(), frames[frames.length - 1][1]);
  }

  function poseIdle(t) {
    const p = basePose();
    const s = Math.sin(t * 3.2);
    p.bob = s * 1.8;
    p.crouch = 2 + s * 1.5;
    p.nU += Math.sin(t * 3.2 + 0.5) * 0.06;
    p.fU += Math.sin(t * 3.2 + 1.1) * 0.05;
    p.head = Math.sin(t * 1.6) * 0.04;
    return p;
  }

  function poseRun(t) {
    const p = basePose();
    const ph = t * 13;
    const swing = Math.sin(ph);
    p.lean = 0.34;
    p.bob = -Math.abs(Math.cos(ph)) * 3 + 1;
    p.crouch = 4;
    // legs: opposite phases, shin trails the thigh and bends on the back-swing
    p.nT = swing * 0.95;
    p.nS = p.nT - (0.45 + 0.55 * Math.max(0, -Math.cos(ph)));
    p.fT = -swing * 0.95;
    p.fS = p.fT - (0.45 + 0.55 * Math.max(0, Math.cos(ph)));
    // arms pump opposite to legs, elbows bent
    p.nU = -swing * 0.75 + 0.15;
    p.nF = p.nU + 1.35;
    p.fU = swing * 0.75 + 0.15;
    p.fF = p.fU + 1.35;
    p.head = 0.08;
    return p;
  }

  function poseJump(t) {
    const p = basePose();
    p.lean = 0.18;
    p.nT = 1.25; p.nS = 0.25;       // knee tucked up
    p.fT = 0.55; p.fS = -0.35;
    p.nU = 2.45; p.nF = 2.75;       // arms reaching up
    p.fU = 1.9;  p.fF = 2.3;
    p.head = -0.1;
    return p;
  }

  function poseFall(t) {
    const p = basePose();
    const fl = Math.sin(t * 11);
    p.lean = 0.05;
    p.nT = 0.55 + fl * 0.08; p.nS = 0.15;
    p.fT = -0.25 - fl * 0.08; p.fS = -0.65;
    p.nU = 1.95 + fl * 0.1; p.nF = 2.4;
    p.fU = 1.7 - fl * 0.1;  p.fF = 2.2;
    p.head = 0.12;
    return p;
  }

  function poseHit(t) {
    const p = basePose();
    const w = Math.sin(t * 26);
    p.lean = -0.55 + w * 0.07;
    p.head = -0.45;
    p.crouch = 6;
    p.nU = 2.3 + w * 0.25; p.nF = 1.7;
    p.fU = 2.0 - w * 0.25; p.fF = 1.4;
    p.nT = 0.9; p.nS = 0.5;
    p.fT = 0.3; p.fS = -0.2;
    return p;
  }

  // --- attacks: u is normalized [0..1] over startup+active+recover,
  //     w1 = end of startup, w2 = end of active ----------------------------

  function poseJab(u, w1, w2) {
    const guard  = {};
    const wind   = { lean: 0.02, nU: -0.45, nF: 0.15, fU: 1.0, fF: 2.1, nT: 0.15, fT: -0.2, crouch: 4 };
    const strike = { lean: 0.42, nU: 1.62, nF: 1.60, fU: -0.3, fF: 0.6, nT: 0.55, nS: 0.35, fT: -0.55, fS: -0.95, crouch: 3, head: 0.1 };
    return kf([[0, guard], [w1, wind], [w1 + (w2 - w1) * 0.3, strike], [w2, strike], [1, guard]], u);
  }

  function poseSmashHammer(u, w1, w2) { // titan: double overhead slam
    const guard  = {};
    const wind   = { lean: -0.42, nU: 3.35, nF: 3.5, fU: 3.25, fF: 3.45, crouch: -2, head: -0.25, nT: 0.1, fT: -0.45 };
    const strike = { lean: 0.55, nU: 1.05, nF: 1.0, fU: 0.95, fF: 0.9, crouch: 10, head: 0.3, nT: 0.6, nS: 0.3, fT: -0.5, fS: -0.9 };
    return kf([[0, guard], [w1 * 0.85, wind], [w1, wind], [w1 + (w2 - w1) * 0.35, strike], [w2, strike], [1, guard]], u);
  }

  function poseSmashKick(u, w1, w2) { // blaze: roundhouse kick
    const guard  = {};
    const wind   = { lean: 0.1, nT: -0.75, nS: -1.5, fT: 0.25, fS: 0.1, nU: 1.1, nF: 2.5, fU: -0.4, fF: 0.8, crouch: 5 };
    const strike = { lean: -0.5, nT: 1.72, nS: 1.70, fT: 0.15, fS: -0.15, nU: -0.6, nF: 0.2, fU: 1.9, fF: 2.5, crouch: 2, head: -0.15 };
    return kf([[0, guard], [w1 * 0.9, wind], [w1, wind], [w1 + (w2 - w1) * 0.3, strike], [w2, strike], [1, guard]], u);
  }

  function poseSmashUpper(u, w1, w2) { // volt: rising uppercut
    const guard  = {};
    const wind   = { lean: 0.35, nU: -0.55, nF: 0.1, fU: 0.9, fF: 2.0, crouch: 14, nT: 0.6, nS: 0.2, fT: -0.5, fS: -1.0, head: 0.2 };
    const strike = { lean: -0.30, nU: 2.95, nF: 3.05, fU: -0.5, fF: 0.3, crouch: -6, nT: 0.35, nS: 0.1, fT: -0.6, fS: -1.1, head: -0.3 };
    return kf([[0, guard], [w1 * 0.9, wind], [w1, wind], [w1 + (w2 - w1) * 0.35, strike], [w2, strike], [1, guard]], u);
  }

  function poseSmashSlash(u, w1, w2) { // shade: katana sweep
    const guard  = {};
    const wind   = { lean: -0.30, nU: 2.95, nF: 3.3, fU: 0.6, fF: 1.6, crouch: 4, head: -0.15, nT: 0.1, fT: -0.4 };
    const strike = { lean: 0.50, nU: 1.15, nF: 1.05, fU: -0.4, fF: 0.4, crouch: 7, head: 0.2, nT: 0.6, nS: 0.35, fT: -0.55, fS: -0.95 };
    return kf([[0, guard], [w1 * 0.85, wind], [w1, wind], [w1 + (w2 - w1) * 0.30, strike], [w2, strike], [1, guard]], u);
  }

  const SMASH_POSES = { blaze: poseSmashKick, titan: poseSmashHammer, volt: poseSmashUpper, shade: poseSmashSlash };

  function getPose(charKey, anim, t) {
    const chr = CHARACTERS[charKey];
    if (anim === 'jab' || anim === 'smash') {
      const a = chr.attacks[anim];
      const total = a.startup + a.active + a.recover;
      const u = clamp01(t / total);
      const w1 = a.startup / total, w2 = (a.startup + a.active) / total;
      if (anim === 'jab') return poseJab(u, w1, w2);
      return (SMASH_POSES[charKey] || poseSmashHammer)(u, w1, w2);
    }
    switch (anim) {
      case 'run':  return poseRun(t);
      case 'jump': return poseJump(t);
      case 'fall': return poseFall(t);
      case 'hit':  return poseHit(t);
      default:     return poseIdle(t);
    }
  }

  // -------------------------------------------------------------------------
  // Skeleton & drawing
  // -------------------------------------------------------------------------

  function joints(charKey, p) {
    const B = BODIES[charKey] || BODIES.blaze;
    const hip = { x: 0, y: -(B.hipBase - p.crouch) + p.bob };
    const sh = { x: hip.x + Math.sin(p.lean) * B.torso, y: hip.y - Math.cos(p.lean) * B.torso };
    const seg = (o, a, L) => ({ x: o.x + Math.sin(a) * L, y: o.y + Math.cos(a) * L });
    const fElb = seg(sh, p.fU, B.upArm), fHand = seg(fElb, p.fF, B.foreArm);
    const nElb = seg(sh, p.nU, B.upArm), nHand = seg(nElb, p.nF, B.foreArm);
    const fKnee = seg(hip, p.fT, B.thigh), fFoot = seg(fKnee, p.fS, B.shin);
    const nKnee = seg(hip, p.nT, B.thigh), nFoot = seg(nKnee, p.nS, B.shin);
    const headC = { x: sh.x + Math.sin(p.lean + p.head) * (B.headR + 4), y: sh.y - Math.cos(p.lean + p.head) * (B.headR + 4) };
    return { B, hip, sh, fElb, fHand, nElb, nHand, fKnee, fFoot, nKnee, nFoot, headC };
  }

  function limb(ctx, a, b, c, w, color) {
    ctx.strokeStyle = color;
    ctx.lineWidth = w;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.lineTo(c.x, c.y);
    ctx.stroke();
  }

  function fist(ctx, pt, r, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(pt.x, pt.y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  function flame(ctx, x, y, r, seed, c1, c2) {
    for (let i = 0; i < 5; i++) {
      const j1 = jitter(seed + i * 3.7), j2 = jitter(seed + i * 9.1);
      ctx.fillStyle = i % 2 ? c1 : c2;
      ctx.globalAlpha = 0.75;
      ctx.beginPath();
      ctx.arc(x + (j1 - 0.5) * r * 2, y + (j2 - 0.5) * r * 2 - i * 2, r * (1 - i * 0.13), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  function spark(ctx, x, y, seed, color) {
    ctx.strokeStyle = color;
    ctx.lineWidth = 2.5;
    for (let i = 0; i < 3; i++) {
      const a = jitter(seed + i * 5.3) * Math.PI * 2;
      const l = 8 + jitter(seed + i * 2.9) * 12;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + Math.cos(a) * l * 0.5, y + Math.sin(a) * l * 0.5);
      ctx.lineTo(x + Math.cos(a + 0.5) * l, y + Math.sin(a + 0.5) * l);
      ctx.stroke();
    }
  }

  function head(ctx, charKey, J, p, t) {
    const chr = CHARACTERS[charKey];
    const { headC, B } = J;
    const r = B.headR;
    // skull
    ctx.fillStyle = chr.skin;
    ctx.beginPath();
    ctx.arc(headC.x, headC.y, r, 0, Math.PI * 2);
    ctx.fill();
    // eye (facing +x)
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(headC.x + r * 0.42, headC.y - r * 0.12, r * 0.30, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#1a1a2e';
    ctx.beginPath(); ctx.arc(headC.x + r * 0.55, headC.y - r * 0.12, r * 0.15, 0, Math.PI * 2); ctx.fill();
    // angry brow
    ctx.strokeStyle = '#1a1a2e'; ctx.lineWidth = 2; ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(headC.x + r * 0.05, headC.y - r * 0.55);
    ctx.lineTo(headC.x + r * 0.75, headC.y - r * 0.35);
    ctx.stroke();

    if (charKey === 'blaze') {
      // spiky hair + headband with flowing tails
      ctx.fillStyle = chr.color1;
      ctx.beginPath();
      ctx.moveTo(headC.x - r, headC.y - r * 0.1);
      for (let i = 0; i < 4; i++) {
        const a = Math.PI * (1.05 + i * 0.24);
        ctx.lineTo(headC.x + Math.cos(a) * r * 1.55, headC.y + Math.sin(a) * r * 1.55);
        ctx.lineTo(headC.x + Math.cos(a + 0.12) * r * 0.95, headC.y + Math.sin(a + 0.12) * r * 0.95);
      }
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = chr.accent;
      ctx.fillRect(headC.x - r, headC.y - r * 0.5, r * 2, r * 0.42);
      ctx.strokeStyle = chr.accent; ctx.lineWidth = 3;
      const fl = Math.sin(t * 7);
      ctx.beginPath();
      ctx.moveTo(headC.x - r, headC.y - r * 0.3);
      ctx.quadraticCurveTo(headC.x - r * 2.2, headC.y + fl * 3, headC.x - r * 3.1, headC.y + 3 + fl * 5);
      ctx.moveTo(headC.x - r, headC.y - r * 0.2);
      ctx.quadraticCurveTo(headC.x - r * 2.0, headC.y + 6 - fl * 3, headC.x - r * 2.8, headC.y + 10 - fl * 5);
      ctx.stroke();
    } else if (charKey === 'titan') {
      // domed helmet with rim
      ctx.fillStyle = chr.color2;
      ctx.beginPath();
      ctx.arc(headC.x, headC.y - r * 0.15, r * 1.12, Math.PI * 0.95, Math.PI * 2.05);
      ctx.fill();
      ctx.fillStyle = shade(chr.color2, 0.7);
      ctx.fillRect(headC.x - r * 1.15, headC.y - r * 0.25, r * 2.3, r * 0.3);
      ctx.fillStyle = chr.accent;
      ctx.beginPath(); ctx.arc(headC.x, headC.y - r * 1.05, r * 0.2, 0, Math.PI * 2); ctx.fill();
    } else if (charKey === 'volt') {
      // lightning-bolt hair
      ctx.fillStyle = chr.color1;
      ctx.beginPath();
      ctx.moveTo(headC.x + r * 0.6, headC.y - r * 0.8);
      ctx.lineTo(headC.x - r * 0.4, headC.y - r * 1.5);
      ctx.lineTo(headC.x - r * 0.1, headC.y - r * 1.0);
      ctx.lineTo(headC.x - r * 1.3, headC.y - r * 1.8);
      ctx.lineTo(headC.x - r * 0.9, headC.y - r * 1.0);
      ctx.lineTo(headC.x - r * 1.6, headC.y - r * 0.6);
      ctx.lineTo(headC.x - r * 0.9, headC.y - r * 0.1);
      ctx.closePath(); ctx.fill();
    } else if (charKey === 'shade') {
      // hood with glowing eye
      ctx.fillStyle = chr.color1;
      ctx.beginPath();
      ctx.arc(headC.x - r * 0.15, headC.y - r * 0.05, r * 1.2, Math.PI * 0.62, Math.PI * 2.25);
      ctx.lineTo(headC.x - r * 1.5, headC.y + r * 0.9);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = chr.accent;
      ctx.beginPath(); ctx.arc(headC.x + r * 0.45, headC.y - r * 0.12, r * 0.18, 0, Math.PI * 2); ctx.fill();
    }
  }

  function katana(ctx, J, p, chr, slashGlow) {
    // blade extends from the near hand along the forearm direction
    const dx = Math.sin(p.nF), dy = Math.cos(p.nF);
    const h = J.nHand;
    const len = 56;
    ctx.strokeStyle = '#3a2a20'; ctx.lineWidth = 6; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(h.x - dx * 8, h.y - dy * 8); ctx.lineTo(h.x + dx * 6, h.y + dy * 6); ctx.stroke();
    if (slashGlow > 0) {
      ctx.shadowColor = chr.accent; ctx.shadowBlur = 14;
    }
    ctx.strokeStyle = '#e8eef5'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(h.x + dx * 6, h.y + dy * 6); ctx.lineTo(h.x + dx * len, h.y + dy * len); ctx.stroke();
    ctx.strokeStyle = '#9fb2c8'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.moveTo(h.x + dx * 6, h.y + dy * 6 - 1.5); ctx.lineTo(h.x + dx * len, h.y + dy * len - 1.5); ctx.stroke();
    ctx.shadowBlur = 0;
  }

  // attack phase: 0 none, 1 windup, 2 active, 3 recover
  function attackPhase(chr, anim, t) {
    if (anim !== 'jab' && anim !== 'smash') return 0;
    const a = chr.attacks[anim];
    if (t < a.startup) return 1;
    if (t < a.startup + a.active) return 2;
    return 3;
  }

  /**
   * Draw a fighter at the current origin (feet at 0,0).
   * opts: { invuln, ghost (alpha), nameTagSkip }
   */
  function drawFighter(ctx, charKey, anim, t, face, opts = {}) {
    const chr = CHARACTERS[charKey] || CHARACTERS.blaze;
    const p = getPose(charKey, anim, t);
    const J = joints(charKey, p);
    const B = J.B;
    const phase = attackPhase(chr, anim, t);

    ctx.save();
    ctx.scale(face, 1);
    if (opts.invuln) ctx.globalAlpha = 0.45 + 0.35 * Math.sin(t * 25);
    if (opts.ghost) ctx.globalAlpha = opts.ghost;

    const farLimb = shade(chr.color1, 0.55);
    const farSkin = shade(chr.skin.startsWith('#') ? chr.skin : '#e8a87c', 0.65);

    // shadow under feet
    ctx.fillStyle = 'rgba(0,0,0,0.18)';
    ctx.beginPath(); ctx.ellipse(0, 2, 26, 6, 0, 0, Math.PI * 2); ctx.fill();

    // far arm & far leg
    limb(ctx, J.sh, J.fElb, J.fHand, B.thick, farLimb);
    fist(ctx, J.fHand, B.thick * 0.62, farSkin);
    limb(ctx, J.hip, J.fKnee, J.fFoot, B.thick + 1, shade(chr.color2, 0.55));
    fist(ctx, J.fFoot, B.thick * 0.6, shade('#33334d', 0.8));

    // torso
    ctx.strokeStyle = chr.color1;
    ctx.lineWidth = B.thick * 2.3;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(J.hip.x, J.hip.y - 2); ctx.lineTo(J.sh.x, J.sh.y + 3); ctx.stroke();
    // belt
    ctx.strokeStyle = chr.accent; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(J.hip.x - B.thick, J.hip.y - 1); ctx.lineTo(J.hip.x + B.thick, J.hip.y - 1); ctx.stroke();
    if (charKey === 'titan') { // rocky pauldron
      ctx.fillStyle = shade(chr.color2, 1.1);
      ctx.beginPath(); ctx.arc(J.sh.x, J.sh.y, B.thick * 1.25, 0, Math.PI * 2); ctx.fill();
    }
    if (charKey === 'shade') { // scarf trail
      ctx.strokeStyle = chr.color2; ctx.lineWidth = 5;
      const fl = Math.sin(t * 6);
      ctx.beginPath();
      ctx.moveTo(J.sh.x - 4, J.sh.y + 4);
      ctx.quadraticCurveTo(J.sh.x - 26, J.sh.y + 8 + fl * 4, J.sh.x - 42, J.sh.y + 2 + fl * 7);
      ctx.stroke();
    }

    // near leg
    limb(ctx, J.hip, J.nKnee, J.nFoot, B.thick + 1, chr.color2);
    fist(ctx, J.nFoot, B.thick * 0.62, '#33334d');
    if (charKey === 'blaze' && anim === 'smash' && phase === 2) {
      flame(ctx, J.nFoot.x, J.nFoot.y, 12, t * 60, '#ff6622', '#ffcc00');
    }

    // head
    head(ctx, charKey, J, p, t);

    // near arm (+ weapon/effects)
    limb(ctx, J.sh, J.nElb, J.nHand, B.thick, chr.color1);
    fist(ctx, J.nHand, B.thick * 0.66, chr.skin);
    if (charKey === 'shade') katana(ctx, J, p, chr, phase === 2 ? 1 : 0);
    if (charKey === 'blaze' && phase >= 1 && phase <= 2 && anim === 'jab') {
      flame(ctx, J.nHand.x, J.nHand.y, phase === 2 ? 11 : 6, t * 60, '#ff6622', '#ffcc00');
    }
    if (charKey === 'volt' && phase === 2) {
      spark(ctx, J.nHand.x, J.nHand.y, t * 60, '#ffee55');
      spark(ctx, J.nHand.x, J.nHand.y, t * 60 + 7, '#aaddff');
    }
    if (charKey === 'titan' && anim === 'smash' && phase === 2) {
      ctx.strokeStyle = 'rgba(216,194,122,0.8)'; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.arc(J.nHand.x, J.nHand.y, 16 + (t * 200) % 10, 0, Math.PI * 2); ctx.stroke();
    }

    // slash / swing arc during active frames
    if (phase === 2 && anim === 'smash') {
      const a = chr.attacks.smash;
      const prog = (t - a.startup) / a.active;
      ctx.globalAlpha *= 0.5 * (1 - prog * 0.6);
      const grad = ctx.createRadialGradient(20, -56, 10, 20, -56, a.range + 20);
      grad.addColorStop(0, chr.trail);
      grad.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(8, -56);
      ctx.arc(8, -56, a.range + 14, -1.2 + prog * 1.4, -0.4 + prog * 1.4);
      ctx.closePath(); ctx.fill();
    }

    ctx.restore();
  }

  const api = { drawFighter, getPose, BODIES, shade };
  if (typeof module === 'object' && module.exports) module.exports = api;
  else window.FIGHTERS = api;
})();
